function buyGoods(s,buyer,c,requested,reason){if(c.status!=='active'||requested<=0||c.stock<=0)return {cash:0,units:0,cost:0};const unit=partners(s,buyer,c.id)?Math.max(1,Math.floor(c.unit*.95)):c.unit;const qty=Math.min(Math.floor(requested),c.stock,Math.floor(account(s,buyer).cash/unit));if(qty<=0)return {cash:0,units:0,cost:0};let n=qty*unit,cost=Math.min(c.stockCost,Math.round(c.stockCost*qty/c.stock));transfer(s,buyer,c.id,n,reason);c.stock-=qty;c.stockCost-=cost;c.revenue+=n;c.costs+=cost;c.sales+=qty;return {cash:n,units:qty,cost};}
