function produce(s){for(const c of s.companies){if(c.status!=='active')continue;const manual=managed(s,c.id),plan=c.strategy,rate=manual?plan.production/100:1;let potential=Math.floor(Math.min(c.capacity,c.workers*2.1)*(0.65+s.services.infrastructure*.0035)),qty=Math.min(Math.floor(potential*rate),Math.max(0,c.capacity*4-c.stock));let wageToStock=potential>0?Math.floor(c.payroll*qty/potential):0;c.costs+=c.payroll-wageToStock;let supplier=manual?idx(s).companies.get(plan.supplier):s.companies.filter(a=>a.id!==c.id&&a.sector===1&&a.status==='active'&&a.stock>0).sort((a,b)=>(a.unit*(partners(s,c.id,a.id)?.95:1))-(b.unit*(partners(s,c.id,b.id)?.95:1)))[0],inputs={cash:0,units:0};const required=Math.ceil(qty*.06);if(supplier?.status==='active'&&required){const price=partners(s,c.id,supplier.id)?Math.floor(supplier.unit*.95):supplier.unit;const maxQty=manual?Math.floor(plan.inputBudget/Math.max(1,price)):required;inputs=buyGoods(s,c.id,supplier,Math.min(required,maxQty),'Производственные поставки');}if(required&&inputs.units<required)qty=Math.floor(qty*(manual?inputs.units/required:.65+.35*inputs.units/required));if(qty===0){c.costs+=wageToStock+inputs.cash;wageToStock=0;inputs.cash=0;}c.stock+=qty;c.stockCost+=wageToStock+inputs.cash;s.daily.production+=qty;let depreciation=Math.min(c.assets,Math.round(c.assets/(365*15)));c.assets-=depreciation;c.costs+=depreciation;}}
function publicSpending(s,residents){const claims=[],pop=residents.length;for(const name of ['health','education','infrastructure','justice'])claims.push({to:name,n:money(pop*s.policy[name]),reason:'Бюджет: '+name});for(const p of residents){const age=p.age/365;if(age>=65)claims.push({to:p.id,n:money(s.policy.pension),reason:'Пенсии'});else if(age<18)claims.push({to:p.id,n:money(s.policy.benefit*.55),reason:'Детские пособия'});else if(!p.employer&&account(s,p.id).cash<money(3000))claims.push({to:p.id,n:money(s.policy.benefit),reason:'Пособие по безработице'});}const total=claims.reduce((n,c)=>n+c.n,0),budget=Math.min(account(s,'treasury').cash,total);let spent=0;for(const c of claims){let n=total?Math.floor(budget*c.n/total):0;if(n)spent+=transfer(s,'treasury',c.to,n,c.reason);}s.daily.budgetRequested=total;s.daily.budgetFunded=spent;}
