function observeCandle(s,c,price,volume=0){
 if(!c.candles)c.candles=[];
 let bar=c.candles[c.candles.length-1];
 if(!bar||bar.day!==s.day){bar={day:s.day,open:price,high:price,low:price,close:price,volume:0};c.candles.push(bar);if(c.candles.length>360)c.candles.shift();}
 bar.high=Math.max(bar.high,price);bar.low=Math.min(bar.low,price);bar.close=price;bar.volume+=volume;
}
function setupPlayerWorld(s){
 s.player.bankCapital??=account(s,'bank').opening;
 s.personalLog??=[];s.tradeHistory??=[];s.government??={lastIndex:s.priceIndex||100,lastDecision:s.day,requests:[]};
 for(const c of s.companies){observeCandle(s,c,c.price);publishReport(s,c);}
 if(!s.npcFunds){s.npcFunds=[];for(let i=0;i<2;i++){let id='nf'+i;addAccount(s,id,['Фонд «Меридиан»','Фонд «Горизонт»'][i],'fund',0);let capital=Math.min(money(3000000),account(s,'p'+i).cash);transfer(s,'p'+i,id,capital,'Учреждение независимого фонда');s.npcFunds.push({id,owner:'p'+i,style:i?'value':'momentum'});}}
 s.market.autoSupport=true;
 press(s,'wire','Астер: рынок открыт','В стране работают независимые предприятия, банки и инвестиционные фонды. Ключевая ставка '+s.policy.rate+'%. Редакции будут следить за крупными сделками и публиковать отчёты компаний.');
}
function auditPlayerWorld(s){if(!Array.isArray(s.tradeHistory)||s.tradeHistory.length>120)throw Error('Повреждён журнал сделок');for(const t of s.tradeHistory){account(s,t.actor);amount(t.qty);amount(t.value);amount(t.price);}
 if(!s.player||typeof s.player.bank!=='boolean'||typeof s.player.fund!=='boolean')throw Error('Повреждены права игрока');
 amount(s.player.bankCapital);if(!s.player.bank&&(account(s,'bank').cash||s.deposits.some(d=>d.bank==='bank'&&d.balance)))throw Error('Неоткрытый банк имеет обязательства');
 if(!s.player.fund&&(units(s)||account(s,'fund').cash||holdings(s,'fund')))throw Error('Неоткрытый фонд имеет активы');
 for(const c of s.companies){if(!Array.isArray(c.candles)||c.candles.length>360)throw Error('Повреждён график');let last=0;for(const b of c.candles){for(const k of ['day','open','high','low','close','volume'])amount(b[k]);if(b.day>s.day||b.day<=last||b.low>Math.min(b.open,b.close)||b.high<Math.max(b.open,b.close)||b.high<b.low)throw Error('Неверная свеча');last=b.day;}}
}
function authorize(s,action,p){
 if(['policy','issue','budget','crash','austerity','crisisPolicy','aid'].includes(action))throw Error('Это решение государства. Игрок не управляет правительством или ЦБ.');
 const bankActions=['loan','bankRate','bankCapital','bankDividend','sue','extend'];
 const fundActions=['fundRaise','fundDecision','fundPolicy','subscribe','redeem'];
 if(bankActions.includes(action)&&!s.player.bank)throw Error('Сначала откройте собственный банк');
 if(fundActions.includes(action)&&!s.player.fund)throw Error('Сначала откройте собственный фонд');
 if(['trade','order'].includes(action)){if(!['player','fund'].includes(p.actor)||(p.actor==='fund'&&!s.player.fund))throw Error('Нет доступа к торговому счёту');}
 if(['companyCapital','borrow'].includes(action)&&!idx(s).companies.has(p.actor))throw Error('Выберите собственное предприятие');
 if(['companyCapital','borrow','loanRequest'].includes(action)){if(!managed(s,p.actor)||(p.actor==='player'))throw Error('Выберите свой бизнес');}
 if(action==='hire'&&!managed(s,p.employer))throw Error('Это не ваш бизнес');
 if(action==='fire'){const t=s.staff.find(t=>t.person===p.id&&t.active);if(!t||!managed(s,t.employer))throw Error('Это не ваш сотрудник');}
 if(action==='loanRepay'){const l=s.loans.find(l=>l.id===p.id);if(!l||!managed(s,l.borrower))throw Error('Это не ваш договор');amount(p.amount);}
 if(action==='cancelOrder'){const o=s.orders.find(o=>o.id===p.id);if(!o||!managed(s,o.actor))throw Error('Это не ваше поручение');}
 if(['deposit','withdrawDeposit'].includes(action)&&p.bank==='bank'&&!s.player.bank)throw Error('Банк ещё не открыт');
}
function openBusiness(s,p){
 const type=p.kind,name=String(p.name||'').trim();amount(p.capital);
 const limits={goods:[100000,5000],industry:[150000,5000],services:[100000,5000],fund:[200000,10000],bank:[5000000,50000]};
 const rule=limits[type];if(!rule||name.length<2||name.length>40)throw Error('Название — от 2 до 40 символов');
 if(p.capital<money(rule[0])||p.capital>money(100000000))throw Error('Минимальный капитал: '+fmt(money(rule[0])));
 const fee=money(rule[1]);if(account(s,'player').cash<p.capital+fee)throw Error('Не хватает личных денег на капитал и регистрацию');
 if(type==='fund'&&s.player.fund||type==='bank'&&s.player.bank)throw Error('Этот бизнес уже открыт');
 if(s.companies.length>=100&&!['fund','bank'].includes(type))throw Error('Достигнут лимит предприятий страны');
 let id;
 if(type==='fund'){id='fund';transfer(s,'player','treasury',fee,'Регистрация инвестиционного фонда');s.player.fund=true;account(s,id).name=name;subscribe(s,'player',p.capital);}
 else if(type==='bank'){id='bank';transfer(s,'player','treasury',fee,'Банковская лицензия');transfer(s,'player',id,p.capital,'Учредительный капитал банка');s.player.bank=true;s.player.bankCapital=p.capital;account(s,id).name=name;idx(s).banks.get(id).frozen=false;}
 else{
  const sector={goods:0,industry:1,services:2}[type],supplier=s.companies.find(c=>c.sector===1&&c.status==='active'&&!managed(s,c.id)&&c.assets>=money(40000));
  if(!supplier)throw Error('Нет поставщика оборудования; попробуйте позже');
  let n=s.companies.length;while(s.accounts['c'+n])n++;let c=company(s,n,0,'player');id=c.id;c.sector=sector;
  c.assets=0;c.stock=0;c.stockCost=0;c.capacity=120;c.jobs=0;c.workers=0;c.wage=money(50);
  c.baseUnit=c.unit=money([32,46,38][sector]);c.price=Math.max(1,Math.floor(p.capital/c.supply));c.history=[c.price];c.reputation=50;c.personality='cautious';c.strategy={production:0,inputBudget:0,supplier:null};c.pendingExpense=0;c.pendingIncome=0;c.manual=true;c.panic=0;c.peakPrice=c.price;c.creditOffer=s.policy.rate+8;c.founded=s.day;account(s,id).name=name;
  transfer(s,'player','treasury',fee,'Регистрация предприятия');transfer(s,'player',id,p.capital,'Учредительный капитал предприятия');
  transfer(s,id,supplier.id,money(40000),'Покупка оборудования для запуска');supplier.assets-=money(40000);supplier.pendingIncome+=money(40000);supplier.pendingExpense+=money(40000);c.assets=money(40000);
  s.portfolio.player[id]={cost:p.capital,realized:0,openingEstimate:false};observeCandle(s,c,c.price);
  // Rebase index for added listed supply; opening a firm is not market appreciation.
  s.market.baseCap+=c.price*c.supply/Math.max(.01,s.market.index/100);
 }
 idx(s).control=null;syncControl(s);event(s,'Бизнес открыт',name+'. Капитал переведён с вашего счёта. '+(type==='bank'?'Установите ставку вкладов и рассмотрите заёмщиков.':type==='fund'?'Сформируйте портфель и выберите инвесторов.':'Выберите поставщика, штат и утвердите производственный план.'));audit(s);return id;
}
function npcWorld(s){if(s.day%7===0)for(const c of s.companies)publishReport(s,c);
 if(s.day%3===0)for(const f of s.npcFunds){const candidates=s.companies.filter(c=>c.status==='active'&&c.price>0),c=candidates[Math.floor(rand(s)*candidates.length)];if(!c)continue;
  const held=c.shares[f.id]||0,side=held&&(s.market.crisis>.3||rand(s)<.35)?'sell':'buy';
  const qty=side==='sell'?Math.min(held,Math.max(10,Math.floor(held*.2))):Math.min(1000,Math.floor(account(s,f.id).cash*.025/Math.max(1,c.price)));
  if(!qty)continue;try{trade(s,c.id,f.id,side,qty);}catch(_){} }
 // NPC creditors make their own recovery decisions.
 if(s.day%14===0)for(const l of s.loans.filter(l=>l.lender!=='bank'&&l.status==='overdue')){
  if(s.cases.some(k=>k.loan===l.id&&['hearing','enforcement','liquidation'].includes(k.status)))continue;
  if(account(s,l.lender).cash<money(7500))continue;
  transfer(s,l.lender,'treasury',money(2500),'Судебная пошлина NPC');transfer(s,l.lender,'law',money(5000),'Юридические услуги NPC');
  s.cases.push({id:'D'+(++s.nextCase),loan:l.id,status:'hearing',due:s.day+21,recovered:0});
 }
}
function requestAid(s,p){
 if(s.government.requests.some(r=>r.actor===p.actor&&r.status==='pending'))throw Error('Заявление уже рассматривается');
 s.government.requests.push({actor:p.actor,day:s.day,due:s.day+3,status:'pending'});
 event(s,'Заявление принято','Государство рассмотрит обращение за 3 дня. Помощь зависит от кризиса, платёжеспособности и бюджета.');
}
function publishReport(s,c){c.publicReport={reportDay:s.day,cash:account(s,c.id).cash,debt:debt(s,c.id),lastProfit:c.lastProfit,revenue:c.revenue,costs:c.costs,workers:c.workers};}
function governmentTick(s){
 const g=s.government;
 for(const r of g.requests)if(r.status==='pending'&&s.day>=r.due){
  let solvent=idx(s).banks.has(r.actor)?bankStats(s)[r.actor].adjusted>0:(()=>{let c=idx(s).companies.get(r.actor);return c?.status==='active'&&account(s,c.id).cash+c.assets+c.stockCost>debt(s,c.id);})();
  if(s.market.crisis>.2&&solvent){try{aid(s,r.actor,Math.min(money(250000),s.market.monthlyLimit-s.market.spent,account(s,'treasury').cash));r.status='accepted';}catch(_){r.status='rejected';}}else r.status='rejected';
  event(s,'Ответ по поддержке',account(s,r.actor).name+': '+(r.status==='accepted'?'возвратный заём одобрен.':'отказ — условия программы не выполнены.'));
 }
 if(s.day%30!==0)return;
 const change=s.priceIndex/Math.max(1,g.lastIndex)-1;g.lastIndex=s.priceIndex;
 if(change>.015&&s.market.crisis<.35)s.policy.rate=Math.min(30,s.policy.rate+.5);
 else if(s.metrics.unemployment>.12&&change<.005)s.policy.rate=Math.max(1,s.policy.rate-.25);
 const cash=account(s,'treasury').cash;
 if(cash<money(30000000)){s.policy.procurement=Math.max(money(20000),Math.floor(s.policy.procurement*.85));s.policy.profitTax=Math.min(30,s.policy.profitTax+.5);
  let available=account(s,'cb').cash,need=Math.max(0,money(5000000)-available);
  if(need&&s.market.crisis>.35){let n=Math.min(need,Math.max(0,Math.floor(s.yearBase*.05)-s.yearIssued));if(n)issue(s,n);}
  pay(s,'cb','treasury',money(5000000),'Финансирование государственного бюджета');
 }else if(s.metrics.unemployment>.12)s.policy.procurement=Math.min(money(350000),Math.round(s.policy.procurement*1.03));
 s.policy.migration=clamp(50+s.metrics.unemployment*100,40,85);
 press(s,'wire','Правительство пересмотрело экономическую политику','Ставка '+s.policy.rate.toFixed(2)+'%, налог на прибыль '+s.policy.profitTax+'%, дневной госзаказ '+fmt(s.policy.procurement)+'. Решение учитывает цены, занятость и средства бюджета. Следующее плановое заседание — через месяц.');
 g.lastDecision=s.day;
}



function previewOrder(s,p){
 const kind=p.kind||'market',a=kind==='limit'?'order':'trade';
 if(!['market','limit'].includes(kind))throw Error('Неизвестный тип заявки');
 authorize(s,a,p);const c=idx(s).companies.get(p.company),q=marketQuote(s,p.company,p.actor,p.side,p.qty);
 if(kind==='limit'){amount(p.limit);if(p.limit<1||!Number.isInteger(p.days)||p.days<1||p.days>90)throw Error('Укажите цену и срок лимитной заявки');}
 const held=c.shares[p.actor]||0,reserved=reservedShares(s,p.actor,c.id),cash=account(s,p.actor).cash;
 const cost=kind==='limit'?p.qty*p.limit:q.total;amount(cost);let error='';
 if(kind==='market'&&q.available!==p.qty)error='Нет встречного объёма на весь пакет. Уменьшите количество акций.';
 if(p.side==='sell'&&p.qty>held-reserved)error='Акций недостаточно: часть отсутствует или зарезервирована.';
 if(p.side==='buy'&&cost>cash)error='Недостаточно свободных денег на торговом счёте.';
 if(!error&&p.side==='buy')try{riskCheck(s,p.actor,c,p.qty,cost);}catch(e){error=e.message;}
 if(kind==='limit'&&s.orders.filter(o=>o.status==='open').length>=30)error='Уже размещено 30 активных заявок.';
 return {...q,fills:undefined,kind,qty:p.qty,actor:p.actor,company:p.company,side:p.side,limit:p.limit,days:p.days,expectedTx:s.tx,expectedDay:s.day,cash,held,reserved,freeShares:held-reserved,reserve:kind==='limit'&&p.side==='buy'?cost:0,cost,cashAfter:p.side==='buy'?cash-cost:kind==='market'?cash+cost:cash,canSubmit:!error,error,counterparties:q.fills.length};
}
function sizeOrder(s,p){
 if(![25,50,75,100].includes(p.percent))throw Error('Размер: 25, 50, 75 или 100%');
 authorize(s,p.kind==='limit'?'order':'trade',p);let c=idx(s).companies.get(p.company);if(!c)throw Error('Компания не найдена');
 if(p.side==='sell')return {qty:Math.min(1000000,Math.floor(Math.max(0,(c.shares[p.actor]||0)-reservedShares(s,p.actor,c.id))*p.percent/100))};
 const budget=Math.floor(account(s,p.actor).cash*p.percent/100);let low=0,high=1000000;
 while(low<high){const n=Math.ceil((low+high)/2);let ok=false;try{const q=previewOrder(s,{...p,qty:n});ok=q.canSubmit&&q.cost<=budget;}catch(_){}if(ok)low=n;else high=n-1;}
 return {qty:low,budget};
}
function liquidityView(s,p){
 authorize(s,'trade',p);
 return {company:p.company,actor:p.actor,day:s.day,tx:s.tx,rows:[10,100,1000,5000].map(qty=>{
  const row={qty};for(const side of ['buy','sell'])try{let q=marketQuote(s,p.company,p.actor,side,qty);row[side]={price:q.price,available:q.available,total:q.total,impact:q.impact};}catch(e){row[side]={error:e.message};}return row;
 })};
}

